const fs=require('fs'), path=require('path'), os=require('os'), crypto=require('crypto'), cp=require('child_process');
const apiVersion='2022-11-28';
function input(n,d=''){return process.env['INPUT_'+n.replace(/ /g,'_').toUpperCase()]??d}
function token(){return input('token')||process.env.GITHUB_TOKEN||process.env.ACTIONS_RUNTIME_TOKEN}
function log(m){console.log(`::notice::${m}`)}
function fail(e){if(String(input('strict')).toLowerCase()!=='true'){console.log(`::warning::cache ignored: ${e.message||e}`);return false} throw e}
async function gh(url,opt={}){let r=await fetch('https://api.github.com'+url,{...opt,headers:{Accept:'application/vnd.github+json','X-GitHub-Api-Version':apiVersion,Authorization:`Bearer ${token()}`,...(opt.headers||{})}});let t=await r.text();let body;try{body=JSON.parse(t)}catch{body=t}if(!r.ok){let e=new Error(`${r.status} ${body.message||t}`);e.status=r.status;e.headers=r.headers;throw e}return {body,headers:r.headers}}
async function upload(url,file,name,type){let b=fs.readFileSync(file);let r=await fetch(url,{method:'POST',headers:{Authorization:`Bearer ${token()}`,'Content-Type':type,'Content-Length':b.length,'X-GitHub-Api-Version':apiVersion},body:b});if(r.ok)return JSON.parse(await r.text());let t=await r.text();let e=new Error(`${r.status} ${t}`);e.status=r.status;throw e}
function run(cmd,args){return cp.execFileSync(cmd,args,{stdio:['ignore','pipe','pipe']})}
function have(cmd){try{run(cmd,['--version']);return true}catch{return false}}
function entries(){return input('path').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}
function makeArchive(){if(!have('tar')||!have('zstd'))throw new Error('tar and zstd are required on the runner');let dir=fs.mkdtempSync(path.join(os.tmpdir(),'cac-'));let out=path.join(dir,'object.tar.zst');let cwd=process.env.GITHUB_WORKSPACE||process.cwd();let list=[];for(let p of entries()){let abs=path.resolve(cwd,p);if(fs.existsSync(abs))list.push(path.relative(cwd,abs)||'.');else log(`cache path missing: ${p}`)}if(!list.length)throw new Error('no cache paths exist');let excludes=input('exclude').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).flatMap(x=>['--exclude',x]);let tar=cp.spawnSync('tar',['--sort=name','--mtime=UTC 1970-01-01','--owner=0','--group=0','--numeric-owner','--format=gnu','-cf','-',...excludes,'-C',cwd,...list],{stdio:['ignore','pipe','inherit']});if(tar.status)throw new Error('tar failed');let z=cp.spawnSync('zstd',['-q',`-${input('compression-level','3')}`,'-o',out],{input:tar.stdout,stdio:['pipe','inherit','inherit']});if(z.status)throw new Error('zstd failed');return {file:out,dir}}
function digest(file){let h=crypto.createHash('sha256');h.update(fs.readFileSync(file));return 'sha256:'+h.digest('hex')}
async function release(repo){try{return (await gh(`/repos/${repo}/releases/tags/cache-v1`)).body}catch(e){if(e.status!==404)throw e;return (await gh(`/repos/${repo}/releases`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tag_name:'cache-v1',name:'Cache objects (v1)',prerelease:true})})).body}}
async function assets(repo){let r=await release(repo);return {release:r,assets:(await gh(`/repos/${repo}/releases/${r.id}/assets?per_page=100`)).body}}
async function object(repo,hash){let a=(await assets(repo)).assets.find(x=>x.name===hash.slice(7)+'.tar.zst');return a}
async function manifest(repo){let r=await gh(`/repos/${repo}/contents/manifests/references-v1.json`);return {json:JSON.parse(Buffer.from(r.body.content,'base64').toString()),sha:r.body.sha}} 
async function refs(repo){try{return await manifest(repo)}catch(e){if(e.status!==404)throw e;return {json:{schema_version:1,references:{}},sha:null}}}
async function setRef(repo,key,hash){for(let i=0;i<5;i++){let m=await refs(repo);m.json.references[key]={object:hash,updated_at:new Date().toISOString()};try{await gh(`/repos/${repo}/contents/manifests/references-v1.json`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:`cache: update ${key}`,content:Buffer.from(JSON.stringify(m.json,null,2)+'\n').toString('base64'),...(m.sha?{sha:m.sha}:{}),branch:'main'})});return}catch(e){if(e.status!==409)throw e}}throw new Error('reference update conflicted after retries')}
async function download(repo,hash){let a=await object(repo,hash);if(!a)throw new Error(`object ${hash} not found`);let d=fs.mkdtempSync(path.join(os.tmpdir(),'cad-')),f=path.join(d,a.name);let r=await fetch(a.browser_download_url,{headers:{Authorization:`Bearer ${token()}`}});if(!r.ok)throw new Error(`download failed: ${r.status}`);fs.writeFileSync(f,Buffer.from(await r.arrayBuffer()));if(digest(f)!==hash)throw new Error('integrity check failed: sha256 mismatch');return f}
function extract(f){let cwd=process.env.GITHUB_WORKSPACE||process.cwd(),tarFile=path.join(path.dirname(f),'object.tar');let p=cp.spawnSync('zstd',['-q','-d','-f',f,'-o',tarFile],{stdio:['ignore','inherit','inherit']});if(p.status)throw new Error('zstd decompression failed');let names=cp.spawnSync('tar',['-tf',tarFile],{encoding:'utf8'});if(names.status)throw new Error(`invalid tar archive: ${names.stderr||'tar listing failed'}`);for(let n of names.stdout.split(/\r?\n/).filter(Boolean)){if(path.isAbsolute(n)||n.split('/').includes('..')||n.split('\\').includes('..'))throw new Error('unsafe archive path')}let q=cp.spawnSync('tar',['--extract','--file',tarFile,'--directory',cwd,'--no-same-owner','--no-same-permissions'],{stdio:['ignore','inherit','inherit']});if(q.status)throw new Error('tar extraction failed')}
module.exports={input,token,log,fail,gh,upload,entries,makeArchive,digest,release,assets,object,refs,setRef,download,extract};
